from textbook_data import sign

G1 = "1. Предупреждающие знаки"
G2 = "2. Знаки приоритета"
G3 = "3. Запрещающие знаки"

sign("1.1", "Железнодорожный переезд со шлагбаумом", G1, "Предупреждает о переезде, оборудованном шлагбаумом. Проезд допускается только при отсутствии запрещающих сигналов и при свободном выезде.", symbol="ЖД")
sign("1.2", "Железнодорожный переезд без шлагбаума", G1, "Предупреждает о переезде без шлагбаума. Безопасность нужно оценивать особенно тщательно по светофорам, дежурному и приближению поезда.", symbol="ЖД")
sign("1.3.1", "Переезд с одним путём", G1, "Обозначает приближение к железнодорожному переезду с одним путём. Не выезжайте на пути при запрете или заторе за ними.", symbol="X")
sign("1.3.2", "Переезд с двумя и более путями", G1, "Обозначает многопутный переезд. После прохода одного поезда проверьте остальные пути: возможен второй состав.", symbol="XX")
sign("1.4.1–1.4.3", "Приближение к железнодорожному переезду", G1, "Дополнительно предупреждают о приближении к переезду. Число наклонных полос помогает оценить последовательность приближения.", symbol="III")
sign("1.5", "Узкая дорога", G1, "Предупреждает о сужении, где встречный разъезд может быть затруднён. Заранее определите преимущество по знакам 2.6 или 2.7.", symbol="↔")
sign("1.6", "Конец дороги с усовершенствованным покрытием", G1, "Предупреждает о переходе на гравийное или грунтовое покрытие. Уменьшите скорость до изменения сцепления колёс с дорогой.", symbol="≈")
sign("1.7", "Пересечение с круговым движением", G1, "Сообщает о приближении к перекрёстку с круговым движением. Заранее выберите полосу и найдите знаки приоритета.", symbol="↻")
sign("1.8", "Светофорное регулирование", G1, "Предупреждает о регулируемом перекрёстке, переходе или участке дороги. Будьте готовы остановиться перед стоп-линией.", symbol="●")
sign("1.9", "Разводной мост или паромная переправа", G1, "Предупреждает об участке, где движение может быть закрыто из-за моста или парома. Выполняйте сигналы и указания обслуживающего персонала.", symbol="≈")
sign("1.10", "Выезд на набережную", G1, "Предупреждает о выезде к берегу или набережной. Не разгоняйтесь на спуске и сохраняйте контроль траектории.", symbol="↓")
sign("1.11.1–1.11.2", "Опасный поворот", G1, "Обозначает поворот малого радиуса или с ограниченной обзорностью вправо либо влево. Снизьте скорость до вхождения и не занимайте встречную полосу.", symbol="↶")
sign("1.12.1–1.12.2", "Опасные повороты", G1, "Предупреждает о нескольких следующих друг за другом опасных поворотах. Первый поворот показан направлением знака.", symbol="S")
sign("1.13", "Крутой спуск", G1, "Обозначает участок спуска, на котором действуют специальные требования. Заранее выберите режим торможения двигателем без перегрева тормозов.", symbol="↘")
sign("1.14", "Крутой подъём", G1, "Обозначает участок подъёма. Учитывайте снижение динамики, возможность медленного транспорта и особые правила встречного разъезда.", symbol="↗")
sign("1.15", "Скользкая дорога", G1, "Предупреждает об участке с возможным уменьшением сцепления. Избегайте резкого руления, разгона и торможения.", symbol="≈")
sign("1.16.1", "Искусственная неровность", G1, "Обозначает одну или несколько искусственных неровностей. Скорость выбирайте так, чтобы сохранить управление и не повредить автомобиль.", symbol="⌒")
sign("1.16.2–1.16.4", "Неровная дорога", G1, "Предупреждает о волнах, наплывах, буграх, выбоинах или просадках покрытия по варианту знака. Держите руль уверенно и увеличьте интервал.", symbol="⌒")
sign("1.17", "Выброс щебня", G1, "Обозначает участок, где из-под колёс возможен выброс щебня. Увеличьте дистанцию и избегайте резких перестроений.", symbol="•")
sign("1.18.1–1.18.6", "Сужение дороги", G1, "Предупреждает о сужении с обеих сторон, справа или слева в зависимости от варианта. Заранее перестройтесь, не вытесняя соседний транспорт.", symbol="↔")
sign("1.19.1–1.19.2", "Двустороннее движение", G1, "Сообщает о начале участка со встречным движением после одностороннего. Держитесь правой стороны и не используйте прежнюю траекторию обгона.", symbol="↑↓")
sign("1.20", "Впереди пешеходный переход", G1, "Предупреждает о приближении к нерегулируемому переходу. Заранее снизьте скорость и наблюдайте за пешеходами по обеим сторонам.", symbol="П")
sign("1.21", "Дети", G1, "Обозначает участок возле детского учреждения, где дети могут неожиданно появиться на дороге. Будьте готовы немедленно остановиться.", symbol="Д")
sign("1.22", "Впереди велосипедный переезд", G1, "Предупреждает о велопереезде со знаками 5.16.3, 5.16.4 или разметкой 1.15. Оценивайте большую скорость приближения велосипедистов.", symbol="В")
sign("1.23", "Дорожные работы", G1, "Обозначает ремонтируемый участок или иные работы. Следуйте временной схеме, не въезжайте в рабочую зону и сохраняйте интервал до людей и техники.", symbol="Р")
sign("1.24", "Перегон скота", G1, "Предупреждает о возможном появлении скота. Не сигналите и не приближайтесь вплотную: животные могут изменить направление.", symbol="Ж")
sign("1.25", "Дикие животные", G1, "Обозначает участок возможного выхода диких животных. В тёмное время особенно контролируйте обочины и снижайте скорость.", symbol="Ж")
sign("1.26", "Падение камней", G1, "Предупреждает об обвалах, оползнях или падении камней. Не останавливайтесь в опасной зоне без необходимости.", symbol="●")
sign("1.27", "Боковой ветер", G1, "Обозначает участок сильного бокового ветра или порывов. Удерживайте траекторию плавно и увеличьте интервал до высоких транспортных средств.", symbol="≈")
sign("1.28", "Низколетящие самолёты", G1, "Предупреждает о возможном шуме и появлении низколетящих воздушных судов. Не допускайте резких действий из-за неожиданного звука.", symbol="✈")
sign("1.29", "Аварийно-опасный участок", G1, "Обозначает место частых ДТП. Повышенное внимание и снижение скорости необходимы даже при отсутствии видимой причины.", symbol="!")
sign("1.30", "Прочие опасности", G1, "Применяется для опасности, которую невозможно обозначить другим предупреждающим знаком. Таблички могут пояснять характер участка.", symbol="!")
sign("1.31.1–1.31.5", "Направление поворота", G1, "Показывает направление движения на повороте малого радиуса, объезде препятствия или разветвлении по варианту знака. Двигайтесь только по указанной стороне.", symbol="›")
sign("1.32", "Опасная обочина", G1, "Предупреждает о заниженной, разрушенной или ремонтируемой обочине. Не съезжайте на неё без крайней необходимости.", symbol="↘")
sign("1.33", "Гололедица", G1, "Обозначает участок возможных снежных заносов, ледяных и снежно-ледяных образований. Увеличьте дистанцию и исключите резкие действия.", symbol="❄")
sign("1.34", "Затор на дороге", G1, "Предупреждает о вероятном скоплении транспорта. Смотрите далеко вперёд и будьте готовы плавно остановиться.", symbol="≡")
sign("1.35", "Сезонные миграции земноводных", G1, "Обозначает участок массового появления земноводных. Проезжайте осторожно, не создавая дополнительной опасности при объезде.", symbol="Ж")
sign("1.36", "Контроль установленной скорости", G1, "Сообщает об автоматическом контроле скорости на участке. Может применяться со знаком 3.24 или содержать его изображение.", "Соблюдайте ограничение на всём участке, а не только около камеры.", "50")
sign("1.37", "Контроль выполнения требований ПДД", G1, "Сообщает об автоматическом контроле соблюдения Правил на участке дороги. Характер контроля не ограничивается только скоростью.", "Соблюдайте сигналы, разметку и порядок движения независимо от видимого оборудования.", "◎")

sign("2.1", "Главная дорога", G2, "Предоставляет преимущество проезда перекрёстка или пересечения проезжих частей. В сочетании со знаком населённого пункта может действовать на всех перекрёстках данной дороги.", symbol="◇")
sign("2.2", "Конец главной дороги", G2, "Отменяет преимущество, предоставленное знаком 2.1. Следующий перекрёсток проезжайте по фактическим знакам и правилам равнозначности.", symbol="◇")
sign("2.3.1", "Пересечение со второстепенной дорогой", G2, "Предупреждает на главной дороге о перекрёстке со второстепенной дорогой вне населённого пункта. Продолжайте контролировать выезжающий транспорт.", symbol="┼")
sign("2.3.2–2.3.3", "Примыкание второстепенной дороги", G2, "Обозначает примыкание второстепенной дороги справа или слева. Преимущество сохраняется, но водитель обязан избегать опасности.", symbol="├")
sign("2.3.4", "Пересечение равнозначных дорог", G2, "Предупреждает о перекрёстке равнозначных дорог. Применяйте правило помехи справа и особые требования к трамваю.", symbol="X")
sign("2.4", "Уступить дорогу", G2, "Требует уступить транспорту на пересекаемой дороге, а с табличкой 7.13 — на главной. На равнозначной дороге учитывается помеха справа. Остановка обязательна только при необходимости уступить.", symbol="▽")
sign("2.5", "Движение без остановки запрещено", G2, "Требует остановиться перед стоп-линией, знаком 5.33 или краем пересекаемой проезжей части, затем уступить. Знак применяется и перед железнодорожным переездом.", symbol="STOP")
sign("2.6.1–2.6.2", "Преимущество встречного движения", G2, "Запрещает въезд на узкий участок, если это затруднит встречное движение. Уступите транспорту на участке и на противоположном подъезде.", symbol="↓↑")
sign("2.7", "Преимущество перед встречным движением", G2, "Предоставляет преимущество на узком участке перед встречным транспортом. Въезжайте только при реальной возможности завершить проезд.", symbol="↑↓")

sign("3.1", "Въезд запрещён", G3, "Запрещает въезд транспортных средств в указанном направлении. Исключения возможны только для транспорта, прямо названного Правилами.", symbol="—")
sign("3.2", "Движение запрещено", G3, "Запрещает движение транспортных средств в зоне действия знака. Не путайте с запретом только въезда в одном направлении.", symbol="")
sign("3.3", "Движение механических транспортных средств запрещено", G3, "Запрещает движение механических транспортных средств. На велосипеде и СПМ применяются собственные нормы и знаки.", symbol="А")
sign("3.4", "Движение грузовых автомобилей запрещено", G3, "Ограничивает грузовые автомобили по технически допустимой или указанной массе, а также указанную технику. Проверьте массу на знаке и таблички.", symbol="Г")
sign("3.5", "Движение мотоциклов запрещено", G3, "Запрещает движение мотоциклов и мопедов. Другие категории оцениваются по остальным знакам и общим правилам.", symbol="М")
sign("3.6", "Движение тракторов запрещено", G3, "Запрещает движение колёсных тракторов и самоходных машин. Запрет не распространяется на транспортные средства, которые следуют по установленным маршрутам и обслуживают предприятия в этой зоне.", symbol="Т")
sign("3.7", "Движение с прицепом запрещено", G3, "Ограничивает грузовые автомобили, тракторы и самоходные машины с прицепами, а также буксировку механических транспортных средств.", symbol="П")
sign("3.8", "Движение гужевых транспортных средств запрещено", G3, "Запрещает движение гужевых транспортных средств, а также животных под седлом, вьюком и прогон скота. Запрет действует на всей ширине дороги в направлении его установки.", symbol="Г")
sign("3.9", "Движение велосипедов запрещено", G3, "Запрещает движение велосипедов. Для СПМ проверьте отдельные знаки и применяемые Правила.", symbol="В")
sign("3.9.1", "Движение на средствах персональной мобильности запрещено", G3, "Запрещает движение на СПМ в зоне знака. Спешившийся человек действует как пешеход, если иное не запрещено.", "Не продолжайте движение по тротуару в объезд запрета. Выберите разрешённый маршрут или ведите СПМ рядом.", "СПМ")
sign("3.10", "Движение пешеходов запрещено", G3, "Запрещает движение пешеходов в обозначенном месте. Используйте другой тротуар или переход.", symbol="П")
sign("3.11.1–3.11.2", "Ограничение массы", G3, "Запрещает движение, если общая фактическая масса транспортного средства или автопоезда превышает значение на знаке.", symbol="т")
sign("3.12.1–3.12.2", "Ограничение нагрузки на ось", G3, "Запрещает движение, если фактическая нагрузка хотя бы на одну ось превышает указанную. Общая масса сама по себе не показывает нагрузку распределения.", symbol="т")
sign("3.13", "Ограничение высоты", G3, "Запрещает проезд транспорта, габаритная высота которого с грузом или без него больше указанной. Измеряйте фактическую высоту после загрузки.", symbol="↕")
sign("3.14", "Ограничение ширины", G3, "Запрещает проезд транспорта шире указанного габарита с грузом или без него. Учитывайте выступающие элементы.", symbol="↔")
sign("3.15.1–3.15.2", "Ограничение длины", G3, "Запрещает движение транспортного средства или автопоезда, длина которого превышает значение на знаке.", symbol="↔")
sign("3.16", "Ограничение минимальной дистанции", G3, "Запрещает движение с дистанцией меньше указанной. Увеличьте расстояние заранее и не допускайте сокращения при перестроениях.", symbol="↔")
sign("3.17.1", "Таможня", G3, "Запрещает проезд без остановки у таможни или контрольного пункта. Дальнейшее движение возможно с разрешения уполномоченного работника.", symbol="!")
sign("3.17.2", "Опасность", G3, "Запрещает движение всех транспортных средств из-за ДТП, аварии, стихийного бедствия или иной опасности.", symbol="!")
sign("3.18.1", "Поворот направо запрещён", G3, "Запрещает только правый поворот в зоне действия. Другие направления определяются остальными знаками и разметкой.", symbol="↱")
sign("3.18.2", "Поворот налево запрещён", G3, "Запрещает только левый поворот на ближайшем пересечении. Разворот при отсутствии иных запретов разрешается, поэтому заранее выберите полосу и не создавайте помех попутному транспорту.", symbol="↰")
sign("3.19", "Разворот запрещён", G3, "Запрещает разворот, но сам по себе не запрещает левый поворот. Проверьте дополнительные ограничения.", symbol="↶")
sign("3.20.1–3.20.2", "Обгон запрещён", G3, "Запрещает обгон с предусмотренным Правилами исключением для одиночных транспортных средств, движущихся медленнее 30 км/ч. Применяйте исключение только при полной безопасности.", symbol="А")
sign("3.20.3", "Обгон транспорта быстрее указанной скорости запрещён", G3, "Запрещает обгон транспортных средств, скорость которых превышает значение на знаке. Оценивайте фактическую скорость обгоняемого.", symbol="30")
sign("3.21.1–3.21.2", "Конец зоны запрещения обгона", G3, "Отменяет зону действия соответствующего знака запрета обгона. Не начинайте манёвр до фактического окончания ограничения.", symbol="А")
sign("3.22", "Обгон грузовым автомобилям запрещён", G3, "Ограничивает обгон грузовыми автомобилями более 3,5 тонны и указанной техникой с предусмотренными исключениями. Масса определяется по правилам знака.", symbol="Г")
sign("3.23", "Конец зоны запрещения обгона грузовым автомобилям", G3, "Отменяет ограничение знака 3.22. Общие запреты обгона и разметка продолжают действовать.", symbol="Г")
sign("3.24.1–3.24.2", "Ограничение максимальной скорости", G3, "Запрещает превышать скорость в км/ч, указанную на знаке. Зона может заканчиваться знаком 3.25, новым ограничением или иной установленной границей.", symbol="50")
sign("3.25.1–3.25.2", "Конец зоны ограничения максимальной скорости", G3, "Отменяет соответствующее ограничение скорости. Общий режим населённого пункта, дороги и другие знаки остаются обязательными.", symbol="50")
sign("3.26", "Подача звукового сигнала запрещена", G3, "Запрещает пользоваться звуковым сигналом, кроме единственного случая — предупреждения о предотвращении дорожно-транспортного происшествия. Обычно знак ставят у больниц, санаториев и в зонах тишины.", symbol="♪")
sign("3.27", "Остановка запрещена", G3, "Запрещает остановку и стоянку в зоне действия, кроме предусмотренных Правилами исключений. Аварийная сигнализация не отменяет запрет.", symbol="X")
sign("3.28", "Стоянка запрещена", G3, "Запрещает стоянку, но не любую краткую остановку. Различие применяется по определениям Правил и табличкам.", symbol="\\")
sign("3.29", "Стоянка запрещена по нечётным числам месяца", G3, "Запрещает стоянку в нечётные числа. Время смены разрешённой стороны определяется специальными правилами, поэтому проверяйте актуальный период.", symbol="I")
sign("3.30", "Стоянка запрещена по чётным числам месяца", G3, "Запрещает стоянку в чётные числа. Действие знаков 3.29 и 3.30 нужно оценивать вместе с правилами перестановки.", symbol="II")
sign("3.31", "Конец зоны всех ограничений", G3, "Отменяет действие ряда запрещающих знаков, перечисленных в приложении 2. Это не отмена любых правил, сигналов и разметки.", symbol="◎")
sign("3.32", "Движение транспортных средств с опасными грузами запрещено", G3, "Запрещает движение с опасными грузами. Табличка может указывать конкретный класс опасности.", symbol="!")
sign("3.33", "Движение с взрывчатыми и легковоспламеняющимися грузами запрещено", G3, "Запрещает перевозку указанных категорий грузов по обозначенному направлению. Специальная перевозка планируется по другому маршруту.", symbol="!")
sign("3.34", "Зона с ограничением максимальной скорости движения", G3, "Обозначает начало территории с указанным ограничением скорости. Режим действует не только до ближайшего перекрёстка, а до конца зоны.", "Соблюдайте ограничение на всей территории до знака 3.35. Не ускоряйтесь после каждого внутреннего выезда.", "30")
sign("3.35", "Конец зоны с ограничением максимальной скорости движения", G3, "Обозначает окончание территории ограничения знака 3.34. После выезда действует общий или вновь установленный режим.", symbol="30")
